import AppKit

func samplerSelfTest(){
    let t=Tracker(frame:NSRect(x:0,y:0,width:1440,height:900)),original=(0..<48000).map{Float($0%511)/255-1};var slots=t.slots;slots[10]=InstrumentSlot(name:"Test WAV",wave:2,pcm:SampleEditing.bytes(original),sampleRate:48000,root:60);t.project.slots=slots;t.instrumentRow=10;t.selectPage(9);precondition(t.samplerFrames==48000&&t.wavePeaks().count==2048)
    var p=t.sampleSettings;p.start=1000;p.end=10000;t.setSampleSettings(p);t.sampleEffect=1;t.applySampleEffect();let reversed=SampleEditing.floats(t.samplerSlot.pcm!);precondition(reversed[999]==original[999]&&reversed[1000]==original[9999]&&reversed[9999]==original[1000]&&reversed[10000]==original[10000]);t.history(true);precondition(t.samplerSlot.pcm==SampleEditing.bytes(original));t.sampleEffect=0;t.applySampleEffect();precondition(t.samplerFrames==9000&&t.sampleSettings.start==0&&t.sampleSettings.end==9000);t.history(true);precondition(t.samplerFrames==48000)
    t.sampleEffect=2;t.sampleBits=4;t.sampleHold=4;t.applySampleEffect();let crushed=SampleEditing.floats(t.samplerSlot.pcm!);precondition(crushed[1000]==crushed[1001]&&crushed[1001]==crushed[1002]&&crushed[999]==original[999]);t.history(true)
    if TimeStretch.executable != nil{t.sampleEffect=5;t.sampleStretch=150;t.applySampleEffect();let stretched=SampleEditing.floats(t.samplerSlot.pcm!);precondition(t.samplerFrames==52500&&t.sampleSettings.end==14500&&stretched[999]==original[999]&&stretched[14500]==original[10000]);t.history(true);precondition(t.samplerFrames==48000&&t.samplerSlot.pcm==SampleEditing.bytes(original))};t.sampleFocus=7;t.changeSampleParameter(1);precondition(t.sampleSettings.octave==1);t.history(true);precondition(t.sampleSettings.octave==nil)
    t.sampleChops=8;t.sampleChop(false);precondition(t.sampleSettings.mode==4&&t.sampleSettings.slices==SampleEditing.evenly(1000,10000,8));t.selectPage(8);t.sampleCursor=2000;t.sampleAddSlice();precondition(t.sampleSettings.slices.contains(2000));t.sampleRemoveSlice();precondition(!t.sampleSettings.slices.contains(2000));t.sampleChop(true);precondition(t.sampleSettings.slices.count==8)
    t.sampleChangeMode(1);precondition(t.sampleSettings.mode==5);t.sampleSoft(1);t.changeSampleParameter(10);precondition(t.sampleSettings.position==550);t.sampleSoft(2);t.changeSampleParameter(1);precondition(t.sampleSettings.grainLength==125);t.sampleSoft(3);t.changeSampleParameter(1);precondition(t.sampleSettings.shape==3);t.sampleSoft(4);t.changeSampleParameter(1);precondition(t.sampleSettings.direction==1);t.sampleSoft(5);t.changeSampleParameter(1);precondition(t.sampleSettings.spread==9)
    t.openPositionAutomation();precondition(t.modal==7);t.adjustPositionAutomation(1);precondition(t.positionAutomation.mode==1);t.automationFocus=1;t.adjustPositionAutomation(1);precondition(t.positionAutomation.shape==1);t.automationFocus=2;t.adjustPositionAutomation(1);precondition(t.positionAutomation.speed==1);t.automationFocus=3;t.adjustPositionAutomation(-1);precondition(t.positionAutomation.depth==95);t.modal=0
    t.openPositionAutomation();t.automationFocus=5;t.adjustPositionAutomation(12);precondition(t.positionAutomation.scan==1&&t.positionAutomation.markerValues[0]==60);t.modal=0
    let data=try! JSONEncoder().encode(t.project),decoded=try! JSONDecoder().decode(Project.self,from:data);precondition(t.valid(decoded)&&decoded.slots?[10].playback==t.sampleSettings);print("Sampler: waveform, start/end, reverse, crop, bitcrusher, slices, granular controls, position LFO, anchors and save passed")
    let r=Tracker(frame:NSRect(x:0,y:0,width:1440,height:900));r.selectPage(10);let destination=r.instrumentRow;precondition(r.slots[destination].name=="EMPTY");tm_capture_begin();let input:[Float]=[0.2,0.4,-0.2,0.1];input.withUnsafeBufferPointer{_ = tm_capture_push($0.baseAddress,nil,Int32($0.count))};r.storeRecording(true,confirm:false);precondition(r.page==8&&r.instrumentRow==destination&&r.slots[destination].pcm==SampleEditing.bytes(input)&&r.sampleSettings.mode==5);r.liveRecorder.discard();r.project.selected=0;var pat=r.pattern;pat.length=32;pat.expanded=true;pat.cells[0][0]=Cell(notes:[60,64,67],instrument:destination,velocity:83,volume:71);pat.trackVolumes=Array(repeating:77,count:24);r.project.patterns[0]=pat;r.copyCurrentPattern(to:2,confirm:false);precondition(r.project.selected==2&&r.pattern.length==32&&r.pattern.cells[0][0].notes==[60,64,67]&&r.pattern.trackVolumes?[0]==77&&r.pattern.activeTrackCount==24);r.row=0;r.track=0;var edited=r.cell;edited.notes=[65];r.cell=edited;precondition(r.project.patterns[0]!.cells[0][0].notes==[60,64,67]);print("Recorded PCM to granular instrument and independent pattern copy passed")
}
